CREATE TABLE CORE_DIM.T_FACT_RETAIL_BY_STORE_DAY_BENCHMARK_1 (
	BUS_DT DATE NOT NULL COMMENT 'The business date to which the measures are related.',
	INT_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the internal organization.',
	parent_int_org_sid NUMBER(38, 0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the internal organization which is the parent in the hierarchy_1 for given internal organization. I.e. if the internal organization is a store, then this attribute is the surrogate key of the sales_1 manager district.',
    parent_int_org_nat_key_nr VARCHAR(250) COMMENT 'The natural key of the internal organization which is the parent in the hierarchy_1 for given internal organization. Benchmarking Szenario/Level: account_1 manager <-> (sales_1) company => sales_company_nr; Benchmarking Szenario/Level: company <-> country_1  => country_org_cd; Benchmarking Szenario/Level: region_1 <-> INT (nternational or all) => fix value for international view of all data (currently ''INT'')',
	BENCHMARKING_TYPE_ID NUMBER(38,0) NOT NULL COMMENT 'The benchmarking type identifies the type of benchmark defined by business departments to view dedicated metrics. It corresponds in general to the hierarchy_1 levels of e.g. the organizational unit_1 hierarchy_1, like - all countries for viewing all records (international view), by country_1, by company (VGES/BGES), by sales_1 manager, etc.',
	INT_ORG_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the discriminators for internal organizations.',
	COUNTRY_ORG_CD VARCHAR(2) NOT NULL COMMENT 'The code of the business country_1 for which the related country_1 organization is responsible. (The business country_1 is not identical to a political country.)',
	TURNOVER_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was generated for that store on the given day. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover for that store up to the given day. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_PY_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was generated for that store on the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_PY_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover for that store up to the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_PY_SWDAY_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was generated for that store on the same weekday one year ago. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_PY_SWDAY_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover for that store up to the same weekday one year ago. (This is the consolidated amount after applying the priority logic.)',
	CASH_REGISTER_TURNOVER_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was generated for that store on the given day according to the cash register.',
	EOD_TURNOVER_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was generated for that store on the given day according to the end-of-day processing of the retail system.',
	BOOKED_TURNOVER_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which has been booked to the store by financial accounting.',
	PLAN_TURNOVER_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which has been planned for that store and that day.',
	PLAN_TURNOVER_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover which has been planned for that store up to the given day.',
	PLAN_TURNOVER_PY_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was planned for that store on the same calendar_1 date one year ago.',
	PLAN_TURNOVER_PY_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover which was planned for that store up to the same calendar_1 date one year ago.',
	PLAN_TURNOVER_PY_SWDAY_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was planned for that store on the same weekday one year ago.',
	PLAN_TURNOVER_PY_SWDAY_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover which was planned for that store up to the same weekday one year ago.',
	TURNOVER_GROSS_VAL NUMBER(38,5) COMMENT 'The gross turnover which was generated for that store on the given day. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_BYTD_GROSS_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the gross turnover for that store up to the given day. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_PY_GROSS_VAL NUMBER(38,5) COMMENT 'The gross turnover which was generated for that store on the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_PY_BYTD_GROSS_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the gross turnover for that store up to the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_PY_SWDAY_GROSS_VAL NUMBER(38,5) COMMENT 'The gross turnover which was generated for that store on the same weekday one year ago. (This is the consolidated amount after applying the priority logic.)',
	TURNOVER_PY_SWDAY_BYTD_GROSS_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the gross turnover for that store up to the same weekday one year ago. (This is the consolidated amount after applying the priority logic.)',
	CASH_REGISTER_TURNOVER_GROSS_VAL NUMBER(38,5) COMMENT 'The gross turnover which was generated for that store on the given day according to the cash register.',
	EOD_TURNOVER_GROSS_VAL NUMBER(38,5) COMMENT 'The gross turnover which was generated for that store on the given day according to the end-of-day processing of the retail system.',
	CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency according to ISO-4217.',
	RECEIPT_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store on the given day. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store up to the given day. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_PY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store on the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_PY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store up to the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_PY_SWDAY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store on the same weekday one year ago. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_PY_SWDAY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store up to the same weekday one year ago. (This is the consolidated amount after applying the priority logic.)',
	CASH_REGISTER_RECEIPT_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store on the given day according to the cash register.',
	EOD_RECEIPT_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store on the given day according ot the end-of-day processing of the retail system.',
	BOOKED_RECEIPT_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been booked to the store by financial accounting.',
	PLAN_RECEIPT_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been planned for that store and that day.',
	PLAN_RECEIPT_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been planned for that store up to that day.',
	PLAN_RECEIPT_PY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been planned for that store on the same calendar_1 date one year ago.',
	PLAN_RECEIPT_PY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been planned for that store up to the same calendar_1 date one year ago.',
	PLAN_RECEIPT_PY_SWDAY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been planned for that store on the same weekday one year ago.',
	PLAN_RECEIPT_PY_SWDAY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been planned for that store up to the same weekday one year ago.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	CONSTRAINT PK_T_FACT_RETAIL_BY_STORE_DAY_BENCHMARK PRIMARY KEY (BUS_DT, INT_ORG_SID, BENCHMARKING_TYPE_ID)
)COMMENT='An aggregate fact holding turnover and customer (receipt) count per day and organizational unit. This fact table is used for benchmarking and contains aggregates on various higher levels of the organiziational hierarchy_1, e.g. country_1 organization. The aggregation level is defined by the benchmarking type.This table supports row-level-security based on policies in the database.'
;